#[derive(Clone, Debug)]
pub struct CSharpLexer<I, H = antlr4_runtime::NoSemanticHooks>
where
    I: CharStream,
    H: antlr4_runtime::SemanticHooks,
{
    base: BaseLexer<I>,
    hooks: H,
}

impl<I> CSharpLexer<I, antlr4_runtime::NoSemanticHooks>
where
    I: CharStream,
{
    pub fn new(input: I) -> Self {
        Self::with_hooks(input, antlr4_runtime::NoSemanticHooks)
    }
}

impl<I, H> CSharpLexer<I, H>
where
    I: CharStream,
    H: antlr4_runtime::SemanticHooks,
{
    pub fn with_hooks(input: I, hooks: H) -> Self {
        let grammar_metadata = metadata();
        let data = grammar_metadata.recognizer_data();
        Self { base: BaseLexer::new(input, data).with_shared_dfa(atn()), hooks }
    }

    pub fn metadata() -> &'static GrammarMetadata {
        metadata()
    }

    /// Adds a listener for lexer diagnostics.
    pub fn add_error_listener<T>(&mut self, listener: T)
    where
        T: for<'a> antlr4_runtime::ErrorListener<dyn antlr4_runtime::Recognizer + 'a> + Send + 'static,
    {
        self.base.add_error_listener(listener);
    }

    /// Removes every lexer error listener, including the default console listener.
    pub fn remove_error_listeners(&mut self) {
        self.base.remove_error_listeners();
    }

    /// Routes every token through ATN interpretation instead of the compiled
    /// lexer DFA, so the learned-DFA trace (`lexer_dfa_string`) observes each
    /// match.
    pub fn set_force_interpreted(&mut self, force_interpreted: bool) {
        self.base.set_force_interpreted(force_interpreted);
    }

    /// Resets this lexer and any caller-owned lifecycle state for reuse.
    pub fn reset(&mut self) {
        if H::ENABLES_LEXER_LIFECYCLE {
            antlr4_runtime::atn::lexer::reset_with_semantic_hooks(
                &mut self.base,
                &mut self.hooks,
            );
        } else {
            self.base.reset();
        }
    }

    /// Replaces the input stream and resets runtime and lifecycle state.
    pub fn set_input_stream(&mut self, input: I) {
        if H::ENABLES_LEXER_LIFECYCLE {
            antlr4_runtime::atn::lexer::set_input_stream_with_semantic_hooks(
                &mut self.base,
                &mut self.hooks,
                input,
            );
        } else {
            self.base.set_input_stream(input);
        }
    }

    /// Clears the learned lexer DFA shared by this grammar.
    pub fn clear_dfa(&self) {
        self.base.clear_dfa();
    }

    fn run_action(_base: &mut BaseLexer<I>, action: antlr4_runtime::LexerCustomAction) -> bool {
        match (action.rule_index(), action.action_index()) {
            (200, 0) => { let _ = lexer_semantics().exec_action(_base, action); true }
            (201, 1) => { let _ = lexer_semantics().exec_action(_base, action); true }
            (202, 2) => { let _ = lexer_semantics().exec_action(_base, action); true }
            (212, 3) => { let _ = lexer_semantics().exec_action(_base, action); true }
            (218, 4) => { let _ = lexer_semantics().exec_action(_base, action); true }
            _ => false,
        }
    }

    fn run_predicate(_base: &BaseLexer<I>, predicate: antlr4_runtime::LexerPredicate) -> Option<bool> {
        match (predicate.rule_index(), predicate.pred_index()) {
            (200, 0) => { Some(lexer_semantics().eval_predicate(_base, predicate).unwrap_or(false)) }
            (201, 1) => { Some(lexer_semantics().eval_predicate(_base, predicate).unwrap_or(false)) }
            (202, 2) => { Some(lexer_semantics().eval_predicate(_base, predicate).unwrap_or(false)) }
            (203, 3) => { Some(lexer_semantics().eval_predicate(_base, predicate).unwrap_or(false)) }
            (204, 4) => { Some(lexer_semantics().eval_predicate(_base, predicate).unwrap_or(false)) }
            _ => Some(true),
        }
    }

}



